-- ════════════════════════════════════════════════════════════════════
-- Kosh MFS — 365 days of transaction history for the EXISTING accounts.
-- Run once in the Supabase SQL Editor, AFTER schema.sql, seed.sql and
-- synthetic-data.sql.
--
-- Period: 2025-07-06 → 2026-07-05 (Asia/Dhaka), the year before the
-- history in synthetic-data.sql (2026-07-06 → 2026-10-03), so together
-- they form one continuous ~15-month history with no overlap.
--
-- • No new users, wallets, profiles or businesses: every row belongs to
--   the 15 accounts already in seed.sql / synthetic-data.sql. Each account
--   only transacts after its own creation / approval date.
-- • 3255 transactions + 344 agent commissions.
--   Ids start with syn_hst_ (scripts/seed-synthetic.mjs --reset removes them too).
-- • Fees and commissions follow src/services/mock/policy.ts. Includes
--   salary-day cash-outs, weekly patterns, Durga Puja, Ramadan,
--   Eid ul-Fitr / Eid ul-Adha and Pohela Boishakh peaks, platform growth.
-- • Wallets: every balance was simulated forward and never goes below
--   zero. At the end the wallets are increased by exactly the money this
--   history leaves behind (plus the agents' opening outlet cash), the
--   same way synthetic-data.sql does it — so the ledger stays consistent.
-- • Ashraful Islam, Sabbir_Tele and Nafiztong get created_at moved back
--   to before their first transaction (only if it is later).
-- Amounts are in paisa (100 = ৳1).
-- ════════════════════════════════════════════════════════════════════

begin;

do $$
begin
  if exists (select 1 from transactions where id like 'syn\_hst\_%') then
    raise exception 'The 365-day history is already there — this script only runs once.';
  end if;
  if (select count(*) from users where id in ('usr_ashraful', 'syn_usr_000011', 'syn_usr_000015', 'syn_usr_000019', 'syn_usr_00001d', 'usr_sabbir_tele', 'syn_usr_000001', 'syn_usr_000005', 'syn_usr_000009', 'syn_usr_00000d', 'usr_nafiztong', 'syn_usr_00000h', 'syn_usr_00000m', 'syn_usr_00000r', 'syn_usr_00000w')) <> 15
     or (select count(*) from wallets where user_id in ('usr_ashraful', 'syn_usr_000011', 'syn_usr_000015', 'syn_usr_000019', 'syn_usr_00001d', 'usr_sabbir_tele', 'syn_usr_000001', 'syn_usr_000005', 'syn_usr_000009', 'syn_usr_00000d', 'usr_nafiztong', 'syn_usr_00000h', 'syn_usr_00000m', 'syn_usr_00000r', 'syn_usr_00000w')) <> 15 then
    raise exception 'Some accounts are missing: run seed.sql and synthetic-data.sql first.';
  end if;
end $$;

update users set created_at = '2025-07-01 04:00:00+00', updated_at = greatest(updated_at, '2025-07-01 04:00:00+00')
 where id in ('usr_ashraful', 'usr_sabbir_tele', 'usr_nafiztong') and created_at > '2025-07-01 04:00:00+00';

-- transactions 2025-07 (117)

-- transactions 2025-08 (150)

-- transactions 2025-09 (190)

-- transactions 2025-10 (203)

-- transactions 2025-11 (172)

-- transactions 2025-12 (243)

-- transactions 2026-01 (271)

-- transactions 2026-02 (298)

-- transactions 2026-03 (455)

-- transactions 2026-04 (334)

-- transactions 2026-05 (397)

-- transactions 2026-06 (354)

-- transactions 2026-07 (71)

-- commissions (344, total ৳3005.31)

-- Opening outlet cash the agents held when this history starts (physical cash, not a transaction).
update wallets set cash_in_hand = coalesce(cash_in_hand, 0) + 25000000 where user_id = 'usr_sabbir_tele';  -- +৳250,000
update wallets set cash_in_hand = coalesce(cash_in_hand, 0) + 12000000 where user_id = 'syn_usr_000001';  -- +৳120,000
update wallets set cash_in_hand = coalesce(cash_in_hand, 0) + 30000000 where user_id = 'syn_usr_000005';  -- +৳300,000
update wallets set cash_in_hand = coalesce(cash_in_hand, 0) + 45000000 where user_id = 'syn_usr_000009';  -- +৳450,000
update wallets set cash_in_hand = coalesce(cash_in_hand, 0) + 20000000 where user_id = 'syn_usr_00000d';  -- +৳200,000

-- This history's effect on every wallet (same rules as the app's ledger).
with eff as (
  select e.user_id, sum(e.avail)::bigint avail, sum(e.cash)::bigint cash, count(*) n
  from transactions t
  cross join lateral (values
    (t.sender_user_id,      -(t.amount + t.sender_fee), 0::bigint),
    (t.receiver_user_id,    t.amount - t.receiver_fee,  0::bigint),
    (t.commission_user_id,  coalesce(t.commission_amount, 0), 0::bigint),
    (t.cash_effect_user_id, 0::bigint, coalesce(t.cash_effect_delta, 0))
  ) e(user_id, avail, cash)
  where t.id like 'syn\_hst\_%' and t.status in ('SUCCESSFUL', 'REFUNDED') and e.user_id is not null
  group by e.user_id
)
update wallets w
   set available = w.available + eff.avail,
       cash_in_hand = case when w.cash_in_hand is null then null else w.cash_in_hand + eff.cash end,
       version = w.version + eff.n::int, updated_at = now()
  from eff
 where w.user_id = eff.user_id;

do $$
begin
  if (select count(*) from transactions where id like 'syn\_hst\_%') <> 3255
     or (select count(*) from commissions where id like 'syn\_hst\_%') <> 344 then
    raise exception 'Row count mismatch — nothing was changed.';
  end if;
  if exists (select 1 from wallets where available < 0 or coalesce(cash_in_hand, 0) < 0) then
    raise exception 'A balance would go negative — nothing was changed.';
  end if;
end $$;

commit;

-- Result: history per month, and the balances now.
select to_char(created_at at time zone 'Asia/Dhaka', 'YYYY-MM') as month, count(*) as transactions,
       sum(amount) filter (where status in ('SUCCESSFUL', 'REFUNDED')) / 100.0 as volume_taka
from transactions group by 1 order by 1;

select u.role, u.name, w.available / 100.0 as balance_taka, w.cash_in_hand / 100.0 as outlet_cash_taka
from users u join wallets w on w.user_id = u.id
order by u.role, u.name;
